effect.shader:
// Pré-calculado uma vez por pixel no passe 1 para não chamar inverse() em cada amostra do laço.
mat3 g_invParaTela;

// A volta do `acTela`: UV da tela → UV do buffer (no filho de grupo; na tela, a identidade).
vec2 daTela(vec2 t) {
    vec3 c = g_invParaTela * vec3(t, 1.0);
    return c.xy / c.z;
}

// O `texture2DCv(inputImg.texture, t)` do AM: a camada pré-multiplicada num ponto da tela, com o filtro da GPU. Na
// tela o buffer É a tela; no filho de grupo, fora do buffer não há camada (o AM a desenha na tela do grupo).
vec4 camadaNaTela(vec2 t) {
    if (acEntradaDePe == 1) return texture(pre, t);
    vec2 uv = daTela(t);
    if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
    return texture(pre, uv);
}

void main() {
    if (acPass == 0) {
        vec4 c = texture(inputImg, acScreenNorm);
        fragColor = vec4(c.rgb * c.a, c.a);
        return;
    }
    g_invParaTela = inverse(acParaTela);

    // O `acScreenNorm` do AM: a UV da tela com t = 0 EMBAIXO. Na tela (`stage="screen"`) a entrada já é a tela, de
    // pé; no filho de grupo, o `acTela` leva o buffer à tela do grupo (também de pé).
    vec2 tela = acEntradaDePe == 1 ? acScreenNorm : acTela(acScreenNorm);
    vec2 acScreenSize = acTamanhoDaTela;

    // A conta do AM, linha por linha. O `getTexSize(inputImg.size)` é o tamanho da camada na tela, em pixels da
    // renderização (a prévia reduzida inclusive).
    vec2 texelSize = 1.0 / vec2(textureSize(pre, 0));
    float rad = angle * 0.0174533;
    vec2 velocity = vec2(cos(rad)*strength,-sin(rad)*strength);
    velocity.x *= acScreenSize.y / acScreenSize.x;
    float speed = length(velocity / texelSize);
    int nSamples = int(clamp(speed, 1.01, 100.01));
    vec4 originalColor = camadaNaTela(tela);
    vec4 outColor = originalColor;
    outColor.rgb = outColor.a > 0.0 ? outColor.rgb/outColor.a : outColor.rgb;
    for(int i=1; i<nSamples; i++ ) {
        vec2 offset = velocity * (float(i) / float(nSamples - 1) - (0.5+bias/2.0));
        vec2 sampleCoord = tela-offset;
        float insideTexture = step(0.0,sampleCoord.x) * step(sampleCoord.x,1.0) * step(0.0,sampleCoord.y) * step(sampleCoord.y,1.0);
        vec4 c = camadaNaTela(sampleCoord) * insideTexture;
        float r;
        float g;
        float b;
        float a;
        if( rmode == 0 ) {
            r = min(outColor.r,c.r);
        } else if( rmode == 1 ) {
            r = max(outColor.r,c.r);
        } else if( rmode == 3 ) {
            r = outColor.r + c.r;
        } else {
            r = outColor.r;
        }
        if( gmode == 0 ) {
            g = min(outColor.g,c.g);
        } else if( gmode == 1 ) {
            g = max(outColor.g,c.g);
        } else if( gmode == 3 ) {
            g = outColor.g + c.g;
        } else {
            g = outColor.g;
        }
        if( bmode == 0 ) {
            b = min(outColor.b,c.b);
        } else if( bmode == 1 ) {
            b = max(outColor.b,c.b);
        } else if( bmode == 3 ) {
            b = outColor.b + c.b;
        } else {
            b = outColor.b;
        }
        if( amode == 0 ) {
            a = min(outColor.a,c.a);
        } else if( amode == 1 ) {
            a = max(outColor.a,c.a);
        } else if( amode == 3 ) {
            a = outColor.a + c.a;
        } else {
            a = outColor.a;
        }
        outColor = vec4(r,g,b,a);
    }
    outColor = outColor / vec4(
        rmode == 3 ? float(nSamples) : 1.0,
        gmode == 3 ? float(nSamples) : 1.0,
        bmode == 3 ? float(nSamples) : 1.0,
        amode == 3 ? float(nSamples) : 1.0
    );
    outColor.rgb *= outColor.a;
    vec4 p = mix(originalColor,outColor,alpha);

    // A saída pré-multiplicada do AM (o alvo de 8 bits dele corta em 0..1) em cor reta.
    p = clamp(p, 0.0, 1.0);
    fragColor = p.a > 0.0 ? vec4(min(p.rgb / p.a, vec3(1.0)), p.a) : vec4(0.0);
}
